from pathlib import Path
import json, difflib

ROOT=Path(__file__).resolve().parents[1]/'rtl_cases_real_scale210_independent_next'

def sva_json(cid, assertions):
    return {'schema_version':'weak-assertions-v1','case_id':cid,'parent_bug_id':cid,
      'source_project':'common_cells','admission_rule':'At least two non-vacuous weak assertions must miss the RTL bug.',
      'overall_validation_status':'pending','assertions':[dict(id=f'W{i}_{k}',weakness_class=k,property=p,
      antecedent=a,antecedent_nonempty=a is not None,expected_weakness=r,validation_status='pending',catches_bug=None,
      nonvacuity_verified=False) for i,(k,p,a,r) in enumerate(assertions,1)]}

def emit(name, module, correct, buggy, spec, golden, weak, tbs, family, signals):
    d=ROOT/name; d.mkdir(parents=True,exist_ok=True)
    (d/'correct.v').write_text(correct,encoding='utf-8')
    (d/'buggy.v').write_text(buggy,encoding='utf-8')
    diff=''.join(difflib.unified_diff(correct.splitlines(True),buggy.splitlines(True),fromfile='correct.v',tofile='buggy.v'))
    (d/'mutation.diff').write_text(diff,encoding='utf-8')
    (d/'spec.md').write_text(spec+'\n',encoding='utf-8')
    (d/'golden.sva').write_text(golden+'\n',encoding='utf-8')
    wj=sva_json(name,weak); (d/'weak_assertions.json').write_text(json.dumps(wj,indent=2)+'\n',encoding='utf-8')
    (d/'weak_assertions.sva').write_text('\n'.join(f'// {a[0]}\nassert property (@(posedge clk_i) disable iff (!rst_ni) ({a[1]}));' for a in weak)+'\n',encoding='utf-8')
    for fn,body in zip(('tb.v','tb_holdout.v','tb_decoy.v'),tbs): (d/fn).write_text(body,encoding='utf-8')
    meta={'name':name,'parent_bug_id':name,'source_project':'common_cells','source_url':'https://github.com/pulp-platform/common_cells.git','source_commit':'local-vendored-snapshot','source_module':module,'source_files':[f'external/common_cells/src/{module}.sv'],'bug_class':'temporal_cross_cycle','bug_family':family,'mutation_kind':'actual_rtl_logic_change','relevant_signals':signals,'temporal_type':'cross-cycle protocol/state transition','status':'candidate_pending_semantic_and_hardness_validation','golden_sva':{'assertion':golden.strip()},'trace_variants':['primary','heldout','decoy'],'first_divergence':{'primary':None,'heldout':None,'decoy':None}}
    (d/'case_metadata.json').write_text(json.dumps(meta,indent=2)+'\n',encoding='utf-8')

credit='''module cc_credit_counter #(parameter integer NumCredits=4, parameter InitCreditEmpty=0)(input clk_i,rst_ni,clr_i,input credit_give_i,credit_take_i,output reg [2:0] credit_o,output credit_left_o,credit_crit_o,credit_full_o);\nwire decrement=credit_take_i & ~credit_give_i; wire increment=~credit_take_i & credit_give_i;\nalways @(posedge clk_i or negedge rst_ni) if(!rst_ni) credit_o<=InitCreditEmpty?0:NumCredits; else if(clr_i) credit_o<=InitCreditEmpty?0:NumCredits; else if(decrement) credit_o<=credit_o-1'b1; else if(increment) credit_o<=credit_o+1'b1;\nassign credit_left_o=credit_o!=0; assign credit_crit_o=credit_o==NumCredits-1; assign credit_full_o=credit_o==NumCredits; endmodule\n'''
credit_b=credit.replace('wire decrement=credit_take_i & ~credit_give_i;','wire decrement=credit_take_i; // MUTATION: simultaneous give/take decrements')

delta='''module cc_delta_counter #(parameter Width=4,parameter StickyOverflow=0)(input clk_i,rst_ni,clr_i,en_i,load_i,down_i,input [Width-1:0] delta_i,d_i,output [Width-1:0] q_o,output overflow_o); reg [Width:0] counter_q; reg overflow_q; wire overflow_clr=clr_i||load_i; wire ov_now=down_i ? delta_i>counter_q[Width-1:0] : counter_q[Width-1:0]>({Width{1'b1}}-delta_i); always @(posedge clk_i or negedge rst_ni) if(!rst_ni) begin counter_q<=0; overflow_q<=0; end else begin if(clr_i) counter_q<=0; else if(load_i) counter_q<={1'b0,d_i}; else if(en_i) counter_q<=down_i?counter_q-delta_i:counter_q+delta_i; if(overflow_clr) overflow_q<=0; else if(en_i&&ov_now) overflow_q<=1; end assign q_o=counter_q[Width-1:0]; assign overflow_o=StickyOverflow?overflow_q:counter_q[Width]; endmodule\n'''
delta_prio=delta.replace('else if(load_i) counter_q<={1\'b0,d_i}; else if(en_i) counter_q<=down_i?counter_q-delta_i:counter_q+delta_i;','else if(en_i) counter_q<=down_i?counter_q-delta_i:counter_q+delta_i; else if(load_i) counter_q<={1\'b0,d_i}; // MUTATION: enable beats load')
delta_clear=delta.replace('wire overflow_clr=clr_i||load_i;','wire overflow_clr=clr_i; // MUTATION: load fails to clear sticky overflow')

trip='''module cc_trip_counter #(parameter Width=4)(input clk_i,rst_ni,clr_i,en_i,input [Width-1:0] delta_i,bound_i,output reg [Width-1:0] q_o,output last_o,trip_o); assign last_o=q_o==bound_i; assign trip_o=last_o&&en_i; always @(posedge clk_i or negedge rst_ni) if(!rst_ni) q_o<=0; else if(clr_i||trip_o) q_o<=0; else if(en_i) q_o<=q_o+delta_i; endmodule\n'''
trip_b='''module cc_trip_counter #(parameter Width=4)(input clk_i,rst_ni,clr_i,en_i,input [Width-1:0] delta_i,bound_i,output reg [Width-1:0] q_o,output last_o,trip_o); reg trip_q; assign last_o=q_o==bound_i; assign trip_o=trip_q; always @(posedge clk_i or negedge rst_ni) if(!rst_ni) begin q_o<=0; trip_q<=0; end else begin trip_q<=last_o&&en_i; if(clr_i||trip_q) q_o<=0; else if(en_i) q_o<=q_o+delta_i; end endmodule\n'''

delay='''module cc_stream_delay #(parameter Width=8,parameter FixedDelay=3)(input clk_i,rst_ni,clr_i,input [Width-1:0] payload_i,input valid_i,output ready_o,output reg [Width-1:0] payload_o,output reg valid_o,input ready_i); reg [7:0] count; reg busy; assign ready_o=!busy; always @(posedge clk_i or negedge rst_ni) if(!rst_ni) begin count<=0;busy<=0;valid_o<=0;payload_o<=0;end else if(clr_i) begin count<=0;busy<=0;valid_o<=0;end else begin if(valid_o&&ready_i) begin valid_o<=0;busy<=0;end if(valid_i&&ready_o) begin payload_o<=payload_i;count<=FixedDelay;busy<=1;end else if(busy&&!valid_o) begin if(count==1) valid_o<=1; else count<=count-1'b1; end end endmodule\n'''
delay_b=delay.replace('count<=FixedDelay;','count<=FixedDelay-1; // MUTATION: output becomes valid one cycle early')

def tb(mod,stim): return f'''`timescale 1ns/1ps\nmodule tb; reg clk_i=0,rst_ni=0,clr_i=0; always #5 clk_i=~clk_i; {stim['decl']} {mod} dut({stim['ports']}); initial begin $monitor("T=%0t {stim['mon']}",$time,{stim['args']}); #2 rst_ni=0; #10 rst_ni=1; {stim['body']} #30 $finish; end endmodule\n'''

wbase=[('single_cycle_implication','clr_i |-> (1\'b1)','clr_i','Checks only the trigger cycle.'),('final_output_only','1\'b1 |-> !$isunknown(q_o)',"1'b1",'Checks only knownness of the final output.'),('delay_removed','en_i |-> (q_o==q_o)','en_i','Removes the required next-cycle relation.'),('antecedent_removed','q_o==q_o',None,'Drops the triggering condition.'),('simple_invariant','q_o>=0',None,'A range invariant cannot establish the transition.')]

# 456
def ctb(body): return tb('cc_credit_counter #(.NumCredits(4))',{'decl':'reg credit_give_i=0,credit_take_i=0; wire [2:0] q_o; wire l,c,f;','ports':'.clk_i,.rst_ni,.clr_i,.credit_give_i,.credit_take_i,.credit_o(q_o),.credit_left_o(l),.credit_crit_o(c),.credit_full_o(f)','mon':'q=%0d give=%b take=%b','args':'q_o,credit_give_i,credit_take_i','body':body})
emit('case456_cc_credit_counter_simultaneous_credit','cc_credit_counter',credit,credit_b,'Simultaneous credit give and take cancel; the stored credit count must remain unchanged.','assert property (@(posedge clk_i) disable iff (!rst_ni) (credit_give_i && credit_take_i) |=> credit_o==$past(credit_o));',wbase,[ctb('#13 credit_take_i=1; #10 credit_take_i=0; #10 credit_give_i=1;credit_take_i=1;#10 credit_give_i=0;credit_take_i=0;'),ctb('#13 credit_take_i=1;#20 credit_take_i=0;credit_give_i=1;#10 credit_take_i=1;#10 credit_give_i=0;credit_take_i=0;'),ctb('#13 credit_take_i=1;#10 credit_take_i=0;#20 credit_give_i=1;credit_take_i=1;#10 credit_give_i=0;credit_take_i=0;')],'simultaneous_handshake_cancellation',['clk_i','rst_ni','clr_i','credit_give_i','credit_take_i','credit_o'])

def dtb(body,sticky=0): return tb(f'cc_delta_counter #(.Width(4),.StickyOverflow({sticky}))',{'decl':'reg en_i=0,load_i=0,down_i=0; reg [3:0] delta_i=1,d_i=0; wire [3:0] q_o; wire overflow_o;','ports':'.clk_i,.rst_ni,.clr_i,.en_i,.load_i,.down_i,.delta_i,.d_i,.q_o,.overflow_o','mon':'q=%0d ov=%b en=%b load=%b','args':'q_o,overflow_o,en_i,load_i','body':body})
emit('case457_cc_delta_counter_load_enable_priority','cc_delta_counter',delta,delta_prio,'A load has priority over enable, including when both are asserted in the same cycle.','assert property (@(posedge clk_i) disable iff (!rst_ni) load_i |=> q_o==$past(d_i));',wbase,[dtb('#13 d_i=9;delta_i=2;load_i=1;en_i=1;#10 load_i=0;en_i=0;'),dtb('#13 d_i=12;load_i=1;#10 load_i=0;#10 d_i=2;delta_i=3;down_i=1;load_i=1;en_i=1;#10 load_i=0;en_i=0;'),dtb('#13 en_i=1;delta_i=2;#20 en_i=0;#10 d_i=7;load_i=1;en_i=1;#10 load_i=0;en_i=0;')],'load_enable_priority',['clk_i','rst_ni','clr_i','en_i','load_i','down_i','delta_i','d_i','q_o'])
emit('case458_cc_delta_counter_sticky_overflow_clear_delay','cc_delta_counter',delta,delta_clear,'In sticky-overflow mode, loading a new counter value synchronously clears overflow.','assert property (@(posedge clk_i) disable iff (!rst_ni) load_i |=> !overflow_o);',wbase,[dtb('#13 d_i=15;load_i=1;#10 load_i=0;en_i=1;delta_i=1;#10 en_i=0;#10 d_i=3;load_i=1;#10 load_i=0;',1),dtb('#13 d_i=0;load_i=1;#10 load_i=0;en_i=1;down_i=1;delta_i=2;#10 en_i=0;#20 d_i=8;load_i=1;#10 load_i=0;',1),dtb('#13 d_i=14;load_i=1;#10 load_i=0;en_i=1;delta_i=3;#10 en_i=0;#30 d_i=1;load_i=1;#10 load_i=0;',1)],'sticky_status_clear_on_load',['clk_i','rst_ni','clr_i','en_i','load_i','q_o','overflow_o'])

def ttb(body): return tb('cc_trip_counter #(.Width(4))',{'decl':'reg en_i=0;reg [3:0] delta_i=2,bound_i=6;wire [3:0] q_o;wire last_o,trip_o;','ports':'.clk_i,.rst_ni,.clr_i,.en_i,.delta_i,.bound_i,.q_o,.last_o,.trip_o','mon':'q=%0d last=%b trip=%b','args':'q_o,last_o,trip_o','body':body})
emit('case459_cc_trip_counter_trip_one_cycle_late','cc_trip_counter',trip,trip_b,'When enable is asserted on the bound, trip is asserted in that cycle and the counter clears on the following edge.','assert property (@(posedge clk_i) disable iff (!rst_ni) (last_o && en_i) |=> q_o==0);',wbase,[ttb('#13 en_i=1;#50 en_i=0;'),ttb('#13 delta_i=3;bound_i=9;en_i=1;#20 en_i=0;#10 en_i=1;#40 en_i=0;'),ttb('#13 delta_i=1;bound_i=3;en_i=1;#70 en_i=0;')],'trip_pulse_and_clear_timing',['clk_i','rst_ni','clr_i','en_i','delta_i','bound_i','q_o','last_o','trip_o'])

def stb(body): return tb('cc_stream_delay #(.Width(8),.FixedDelay(3))',{'decl':'reg [7:0] payload_i=0;reg valid_i=0,ready_i=1;wire ready_o,valid_o;wire [7:0] payload_o;','ports':'.clk_i,.rst_ni,.clr_i,.payload_i,.valid_i,.ready_o,.payload_o,.valid_o,.ready_i','mon':'vin=%b rin=%b vout=%b data=%h','args':'valid_i,ready_o,valid_o,payload_o','body':body})
wd=[('single_cycle_implication','valid_i && ready_o |-> !valid_o','valid_i && ready_o','Only checks the acceptance cycle.'),('final_output_only','valid_o |-> payload_o==$past(payload_i,3)','valid_o','Ignores whether valid asserted too early.'),('delay_removed','valid_i && ready_o |=> valid_o || !valid_o','valid_i && ready_o','Removes the exact delay.'),('antecedent_removed','!$isunknown(payload_o)',None,'Drops input acceptance.'),('simple_invariant','valid_o |-> !ready_o','valid_o','Local status does not prove latency.')]
emit('case460_cc_stream_delay_exact_delay_minus_one','cc_stream_delay',delay,delay_b,'An accepted transaction becomes valid exactly FixedDelay cycles later, never earlier.','assert property (@(posedge clk_i) disable iff (!rst_ni) (valid_i && ready_o) |-> ##3 valid_o);',wd,[stb('#13 payload_i=8\'hA5;valid_i=1;#10 valid_i=0;'),stb('#23 payload_i=8\'h3C;valid_i=1;#10 valid_i=0;#20 ready_i=0;#20 ready_i=1;'),stb('#13 payload_i=8\'h11;valid_i=1;#10 valid_i=0;#60 payload_i=8\'hE7;valid_i=1;#10 valid_i=0;')],'exact_configured_latency',['clk_i','rst_ni','clr_i','valid_i','ready_o','payload_i','valid_o','ready_i','payload_o'])
